import{_ as a,o,c as r,a2 as s}from"./chunks/framework.B_GyVC5q.js";const g=JSON.parse('{"title":"Notas de la versión","description":"","frontmatter":{"title":"Notas de la versión"},"headers":[],"relativePath":"release-notes/es.md","filePath":"release-notes/es.md"}'),n={name:"release-notes/es.md"};function i(t,e,l,d,c,u){return o(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="notas-de-version" tabindex="-1">Notas de versión <a class="header-anchor" href="#notas-de-version" aria-label="Permalink to &quot;Notas de versión&quot;">​</a></h1><hr><h2 id="_1-5-x" tabindex="-1">1.5.x <a class="header-anchor" href="#_1-5-x" aria-label="Permalink to &quot;1.5.x&quot;">​</a></h2><h3 id="resumen" tabindex="-1">Resumen <a class="header-anchor" href="#resumen" aria-label="Permalink to &quot;Resumen&quot;">​</a></h3><p>La versión <code>1.5.x</code> añade <strong>Flujos</strong> (lienzo visual para pipelines de datos/peticiones con ejecución/depuración, plantillas, biblioteca, importación/exportación e IA de Flows); <strong>zip</strong> en Generar / <strong>Repetir cada</strong> para semillas padre–hijo rápidas; logos y retratos SVG locales; IA de Flows que <strong>construye y optimiza</strong> grafos; añade <strong>acciones y tareas de IA</strong> (Generar datos / Consultar dataclass con historial en el pie); añade <strong>Relaciones</strong> (lienzo orbital para enlaces N:1, centrar, desvincular, historial y duplicar con selección); añade <strong>plan y ruta de consulta</strong>, <strong>Copiar como</strong>, <strong>Copiar sesión</strong> en escritorio, <strong>zoom de imagen</strong>, alojamiento <strong>Docker</strong>, el <strong>playground de plantillas</strong> de entorno y mejoras de formularios de entidad (campos booleanos, campo de carga, vaciar antes de insertar); y pule los límites/vista previa de anonimización, los recuentos/recarga del catálogo, el estado en línea, el manejo de claves de relación, el teclado móvil, los filtros de registro de consola, los registros de flujo detallados (incluido contraer todo), los toasts compactos y la apertura de enlaces en escritorio.</p><h3 id="funciones" tabindex="-1">Funciones <a class="header-anchor" href="#funciones" aria-label="Permalink to &quot;Funciones&quot;">​</a></h3><h4 id="flujos" tabindex="-1">Flujos <a class="header-anchor" href="#flujos" aria-label="Permalink to &quot;Flujos&quot;">​</a></h4><ul><li><strong>Espacio de trabajo de flujos</strong> — Ábralo desde el control <strong>Flujos</strong> del pie, la paleta de comandos (<strong>Flujos</strong>) o la pantalla de bienvenida. Construya pipelines en un lienzo con anclas Inicio/Fin, una paleta de bloques, un esquema y un inspector.</li><li><strong>Biblioteca</strong> — Guarde flujos por base; busque, duplique, elimine, borrar todo; importar / exportar / copiar JSON.</li><li><strong>Plantillas</strong> — Parta del Tour de operadores, Evaluate y lógica, Consultar datos, HTTP · Ping <code>$info</code>, o Archivos de confianza.</li><li><strong>Bloques de datos y red</strong> — Listar (multi-dataclass), Crear, Generar, Actualizar, Purgar (consulta / conjunto de entidades / dataclass completa), Importar CSV, HTTP y Método (catálogo / singleton / dataclass / entidad).</li><li><strong>Bloques de entrada</strong> — Inyectar una carga (incluidos números <code>$faker</code>), ticks de Intervalo (<code>{ counter, timestamp }</code>) y Marca de tiempo — fuentes que disparan al iniciar (sin cable de entrada).</li><li><strong>Código y lógica</strong> — Asignar variables, Evaluar (TypeScript aislado <code>main()</code>), Si / Para / <strong>Repetir cada</strong> / Retraso, Registro, Cronología, Nota (Markdown, omitida en ejecución) y bloques de instrucción IA.</li><li><strong>Operadores de flujo</strong> — Map, Filter, Take, Merge, ForkJoin, Buffer, Debounce y operadores relacionados al estilo RxJS para componer pipelines. Las descripciones emergentes de la paleta y el lienzo enlazan a la documentación oficial de RxJS para operadores con nombre.</li><li><strong>Ejecución y depuración</strong> — Ejecutar, pausa/reanudar, detener, paso a paso; puntos de interrupción por bloque con activación/desactivación global; seguir el paso actual en el lienzo; registro de ejecución, watches y consola de evaluación en el punto de interrupción.</li><li><strong>Registro de ejecución detallado</strong> — Opción <strong>Detallado</strong> junto a dry run. Cada bloque registra pendiente y luego hecho (o error) con duración, entradas y salidas desplegables (el mismo árbol de objetos que la Consola). Duración y copiar quedan junto al texto. <strong>Contraer todo</strong> (barra de herramientas, menú overflow o menú contextual del registro) pliega las filas y árboles expandidos sin borrar el registro.</li><li><strong>Bloques Nota</strong> — Las notas Markdown son solo documentación: se omiten en ejecución y no se pueden desactivar ni recibir un punto de interrupción.</li><li><strong>Ejecutar en el servidor</strong> — Cuando la base expone <code>FlowRunner</code> y el flujo no tiene nodos solo de cliente; los flujos con carpetas de confianza siguen exigiendo escritorio o móvil.</li><li><strong>IA de Flows</strong> — Chat acoplado para <strong>crear flujos rápidos</strong> desde una instrucción y <strong>refactorizar</strong> el grafo (generate por lotes, zip de FK, repeatEach). Sugerencias que incluyen <strong>Optimizar velocidad</strong>. Configure un LLM en Ajustes.</li><li><strong>Zip en Generar</strong> — FK secuenciales: la fila <code>i</code> copia <code>entities[i]</code> de un generate anterior (ruta <code>from</code> como <code>nodes.addr.stdout.entities</code>, <code>attr</code> por defecto <code>ID</code>). El recuento sigue la lista padre. Prefiéralo a <code>$pick</code> cuando cada padre deba tener un número garantizado de hijos.</li><li><strong>Repetir cada</strong> — Bloque lógico que repite cada entidad de entrada N veces (literal o <code>{{$faker.number.int | between:10,50}}</code> por padre). Úselo con zip para «10–50 empleados por empresa» sin un bucle Para + Crear.</li><li><strong>Faker por fila en Generar</strong> — Las plantillas <code>$faker</code> / <code>$pick</code> siguen sin resolverse hasta crear cada entidad, así que nombres, direcciones y medios varían en el lote (createMany).</li><li><strong>Logos y retratos SVG locales</strong> — <code>{{$faker.company.logo}}</code> y <code>{{$faker.image.personPortrait}}</code> producen data URI SVG compactas (<code>female</code> / <code>male</code> opcionales). Sin petición CDN antes de <code>$upload</code>.</li><li><strong>CSV y relaciones</strong> — Importaciones CSV al estilo dataInit con columnas de relación <code>$rel_*</code>, oleadas ordenadas por dependencias y opción omitir-si-no-vacío.</li><li><strong>Campos de IA alineados con el catálogo</strong> — Reasigne claves de campos de IA a atributos reales del catálogo; rellene claves foráneas de entidades relacionadas desde <code>{{item.__KEY}}</code> al generar filas vinculadas.</li></ul><h4 id="acciones-y-tareas-de-ia" tabindex="-1">Acciones y tareas de IA <a class="header-anchor" href="#acciones-y-tareas-de-ia" aria-label="Permalink to &quot;Acciones y tareas de IA&quot;">​</a></h4><ul><li><strong>Menú de acciones de IA</strong> — En listas de dataclass, filas de la barra lateral y el grafo de estructura: <strong>Generar datos</strong>, <strong>Consultar dataclass</strong> y generar filtro/params (requiere LLM).</li><li><strong>Tareas de IA</strong> — Historial en el pie para ejecuciones en segundo plano; cancelar una o todas; diálogos de confirmación para pasos destructivos; inspección de actividad/traza.</li></ul><h4 id="consultas-y-peticiones" tabindex="-1">Consultas y peticiones <a class="header-anchor" href="#consultas-y-peticiones" aria-label="Permalink to &quot;Consultas y peticiones&quot;">​</a></h4><ul><li><strong>Plan y ruta de consulta</strong> — Active <code>$queryplan</code> / <code>$querypath</code> en el Query Builder, el Cliente HTTP y el Ejecutor de métodos; inspeccione acceso por índice vs secuencial, uniones, tiempos y JSON.</li><li><strong>Copiar como</strong> — Copie la petición actual o una entrada de red de la consola como código ejecutable (<code>HTTPRequest</code> 4D, cURL, JavaScript, Python y otros destinos).</li></ul><h4 id="escritorio-y-alojamiento" tabindex="-1">Escritorio y alojamiento <a class="header-anchor" href="#escritorio-y-alojamiento" aria-label="Permalink to &quot;Escritorio y alojamiento&quot;">​</a></h4><ul><li><strong>Copiar sesión</strong> — Inicie sesión en el navegador desde la pantalla de conexión; confirme para enviar las cookies de sesión a la app de escritorio (instale la clase descargable <code>CopySession</code>).</li><li><strong>Docker</strong> — Ejecute la imagen publicada o construya desde <code>DataExplorer.zip</code> con <code>BACKEND_URL</code> (véase Getting started).</li><li><strong>Zoom de escritorio</strong> — Menú Vista Acercar / Alejar / Tamaño real.</li></ul><h4 id="entornos-y-plantillas" tabindex="-1">Entornos y plantillas <a class="header-anchor" href="#entornos-y-plantillas" aria-label="Permalink to &quot;Entornos y plantillas&quot;">​</a></h4><ul><li><strong>Playground de plantillas</strong> — Conmutador de entorno → <strong>Probar…</strong> para evaluar plantillas, <code>$faker</code>, filtros y <code>$this</code> con ejemplos.</li><li><strong>Filtros pipe</strong> — Transformaciones adicionales, incluidas <code>capitalize</code>, <code>title</code>, variantes trim, <code>take_before</code> / <code>take_after</code>, <code>remove</code> / <code>replace</code>, padding y <code>default</code>.</li></ul><h4 id="formularios-de-entidad-y-medios" tabindex="-1">Formularios de entidad y medios <a class="header-anchor" href="#formularios-de-entidad-y-medios" aria-label="Permalink to &quot;Formularios de entidad y medios&quot;">​</a></h4><ul><li><strong>Campos booleanos</strong> — Casilla y edición bool-o-plantilla para atributos booleanos.</li><li><strong>Campo de carga</strong> — Campos imagen/blob con selección de archivo, arrastrar y soltar, plantillas de carpetas de confianza y limpieza del estado de carga.</li><li><strong>Vaciar antes de insertar</strong> — Opcionalmente elimine todas las entidades de la dataclass antes de crear por lotes (con confirmación).</li><li><strong>Concurrencia de carga de medios</strong> — Materialización de medios en paralelo y con caché para creación multi-entidad, anonimización y flujos.</li><li><strong>Tratar la clave de relación 0 como vacía</strong> — Opción de Ajustes para que las relaciones diferidas con clave <code>0</code> se muestren vacías en lugar de cargarse.</li></ul><h4 id="relaciones" tabindex="-1">Relaciones <a class="header-anchor" href="#relaciones" aria-label="Permalink to &quot;Relaciones&quot;">​</a></h4><ul><li><strong>Lienzo Relaciones</strong> — Explore los enlaces many-to-one de un registro en un grafo orbital (centro + anillo). Ábralo desde la paleta de comandos (<strong>Relaciones</strong>), el menú <strong>⋯</strong> de tarjetas o tabla, el visor de entidad o las celdas de entidad del terminal.</li><li><strong>Seleccionar vs Centrar</strong> — Haga clic en un registro vinculado para inspeccionarlo en el panel de detalles sin recentrar; <strong>Centrar</strong> expande su vecindario N:1 y recentra el lienzo.</li><li><strong>Radios y desvincular</strong> — Haga clic en un radio de relación para ver los detalles del enlace; <strong>Desvincular</strong> borra la clave foránea (con confirmación) sin eliminar el registro relacionado.</li><li><strong>Historial y zoom</strong> — Historial de selección atrás/adelante; acercar, alejar y ajustar (barra de herramientas, rueda del ratón o ⌘/Ctrl +/− / 0 con el lienzo enfocado).</li><li><strong>Duplicar</strong> — Confirmación antes de duplicar un registro en el lienzo; el toast de éxito ofrece <strong>Seleccionar</strong> para centrar el nuevo registro.</li><li><strong>Acciones de fila</strong> — Las acciones de lista y tarjeta de entidad pasan por un único menú <strong>⋯</strong> (Relaciones, copiar JSON, duplicar, eliminar).</li></ul><h4 id="herramientas-de-seleccion-y-ux-de-medios" tabindex="-1">Herramientas de selección y UX de medios <a class="header-anchor" href="#herramientas-de-seleccion-y-ux-de-medios" aria-label="Permalink to &quot;Herramientas de selección y UX de medios&quot;">​</a></h4><ul><li><strong>Límite y vista previa de anonimización</strong> — Limite cuántas entidades anonimizar; vea límite vs conjunto de entidades vs totales de dataclass; vista previa más rica antes de ejecutar.</li><li><strong>Zoom de imagen</strong> — Abra las imágenes en una vista previa con zoom y desplazamiento (+ / − / 0, rueda, arrastrar).</li></ul><h4 id="catalogo-y-conectividad" tabindex="-1">Catálogo y conectividad <a class="header-anchor" href="#catalogo-y-conectividad" aria-label="Permalink to &quot;Catálogo y conectividad&quot;">​</a></h4><ul><li><strong>Recuentos de dataclass</strong> — Cargue recuentos de entidades bajo demanda (automático si el catálogo es pequeño) para totales y gráficos de Inicio.</li><li><strong>Recargar catálogo</strong> — Vacíe la caché y recargue desde estados vacíos / de error.</li><li><strong>Estado en línea</strong> — Indicador sin conexión en el pie; la IA en la nube y las actualizaciones se pausan, mientras que REST en LAN y los LLM locales siguen disponibles.</li><li><strong>Filtro de registro de consola</strong> — Niveles de selección múltiple (log, info, warn, error, red) con un control triestado <strong>Todos los registros</strong>.</li><li><strong>Retención de registros</strong> — Límite de registros de flujos y límite de la consola: <code>0</code> conserva todas las entradas hasta que vacíe el registro.</li><li><strong>Quitar entrada de consola</strong> — Elimine líneas individuales del registro de consola o de red.</li><li><strong>Restablecer selección</strong> — Ejecutar una nueva consulta borra la selección múltiple anterior para que los resultados sigan sincronizados.</li><li><strong>Toasts compactos</strong> — Los toasts de éxito y error son más densos, con acciones en línea junto al título cuando hace falta.</li></ul><h3 id="documentacion" tabindex="-1">Documentación <a class="header-anchor" href="#documentacion" aria-label="Permalink to &quot;Documentación&quot;">​</a></h3><ul><li>Páginas de la guía <a href="https://midrissi.github.io/4d-dataexplorer/guide/flows.html" target="_blank" rel="noreferrer">Flujos</a> (zip en Generar, Repetir cada, registro detallado, contraer todo, Notas, docs RxJS), <a href="https://midrissi.github.io/4d-dataexplorer/guide/console.html" target="_blank" rel="noreferrer">Consola</a> (filtro de nivel), <a href="https://midrissi.github.io/4d-dataexplorer/guide/trusted-folders.html" target="_blank" rel="noreferrer">Carpetas de confianza</a> (cuadrícula de iconos), <a href="https://midrissi.github.io/4d-dataexplorer/guide/ai-actions.html" target="_blank" rel="noreferrer">Acciones y tareas de IA</a>, <a href="https://midrissi.github.io/4d-dataexplorer/guide/getting-started.html#run-with-docker" target="_blank" rel="noreferrer">Docker</a>, plan de consulta (Query Builder / Cliente HTTP / Ejecutor de métodos), Copiar como, y Copiar sesión (escritorio macOS).</li></ul><h3 id="correcciones" tabindex="-1">Correcciones <a class="header-anchor" href="#correcciones" aria-label="Permalink to &quot;Correcciones&quot;">​</a></h3><ul><li><strong>Unicidad de Generar</strong> — Generar ya no estampa un solo valor faker resuelto en todas las filas clonadas.</li><li><strong>Retratos</strong> — <code>$faker.image.personPortrait</code> ya no depende de una URL de imagen remota.</li><li><strong>Teclado virtual móvil</strong> — Los editores permanecen por encima del teclado en pantalla para que los campos sigan visibles al escribir.</li><li><strong>Consola con muchas imágenes</strong> — Las miniaturas de carpetas de confianza ya no inundan la consola; la vista de iconos permanece virtualizada para que las carpetas grandes no congelen la UI.</li><li><strong>Solapamiento de la cuadrícula de iconos</strong> — Las teselas mantienen una altura de miniatura fija, parten los nombres sin cortar la extensión y muestran el tipo como insignia atenuada bajo el nombre (no sobre la imagen).</li><li><strong>Zoom de página de escritorio</strong> — ⌘/Ctrl + inercia del trackpad ya no hace zoom al soltar el modificador; el zoom solo se aplica si el gesto empezó con ⌘ o Ctrl.</li><li><strong>Enlaces externos de escritorio</strong> — Los enlaces <code>https</code> / <code>http</code> / <code>mailto</code> (incluida la documentación RxJS de los operadores) se abren una sola vez en el navegador del sistema. Recompile la app de escritorio para que se apliquen los permisos de apertura.</li></ul><h2 id="_1-4-x" tabindex="-1">1.4.x <a class="header-anchor" href="#_1-4-x" aria-label="Permalink to &quot;1.4.x&quot;">​</a></h2><h3 id="resumen-1" tabindex="-1">Resumen <a class="header-anchor" href="#resumen-1" aria-label="Permalink to &quot;Resumen&quot;">​</a></h3><p>La versión <code>1.4.x</code> añade <strong>variables de entorno</strong> (capas globales, perfil y base con <code>{{templates}}</code>, filtros pipe y dinámicas Faker); añade <strong>carpetas de confianza</strong> en escritorio y móvil (plantillas <code>{{$files.alias}}</code> para <code>$upload</code>); añade el <strong>terminal ORDA</strong> (modos REPL y Código con archivos snippet) en un dock inferior compartido con la Consola; añade <strong>exportación REST</strong> (colección v2.1 y OpenAPI 3.1 desde el catálogo, el Cliente HTTP y el Ejecutor de métodos); añade <strong>herramientas de selección</strong> (análisis <code>$distinct</code> / <code>$compute</code>, exportación/importación multi-formato y anonimización Faker con descarga, importar como nuevos o actualización in situ); añade <strong>favoritos</strong> para el Cliente HTTP y el Ejecutor de métodos; publica las apps <strong>iOS y Android</strong>; mejora el Ejecutor de métodos (params/cabeceras Advanced, <code>$method=entityset</code> por defecto, errores en el panel de resultado, estados vacíos y atajos mod-clic); mejora el registro de red de la consola (cuerpo en pending, abrir mientras pending, cancelar); y pule la UX móvil (Cliente HTTP y dock).</p><h3 id="funciones-1" tabindex="-1">Funciones <a class="header-anchor" href="#funciones-1" aria-label="Permalink to &quot;Funciones&quot;">​</a></h3><h4 id="variables-de-entorno" tabindex="-1">Variables de entorno <a class="header-anchor" href="#variables-de-entorno" aria-label="Permalink to &quot;Variables de entorno&quot;">​</a></h4><ul><li><strong>Editor de entornos</strong> — Gestione los ámbitos <strong>Globals</strong>, <strong>Perfil</strong> y <strong>Esta base</strong> desde Herramientas, la paleta de comandos (<strong>Entornos</strong>) o el conmutador <strong>Environment</strong> del pie → <strong>Gestionar…</strong>.</li><li><strong>Entornos activos</strong> — Un entorno de perfil y uno de base activos a la vez; el conmutador del pie los selecciona y previsualiza la lista fusionada (los secretos permanecen enmascarados hasta revelarlos).</li><li><strong>Plantillas</strong> — Inserte <code>{{name}}</code> en el Cliente HTTP, el Ejecutor de métodos, el Query Builder, Crear entidad, snippets del terminal ORDA y otros campos con plantilla; se resuelven al enviar/ejecutar.</li><li><strong>Filtros pipe</strong> — Transformaciones estilo Liquid (<code>upper</code>, <code>lower</code>, <code>replace</code>, <code>unwrap</code>, <code>substring</code>, <code>hash:md5</code>, …) y opciones de generación (<code>female</code> / <code>male</code>, <code>min</code> / <code>max</code> / <code>between</code>, <code>after</code> / <code>before</code>).</li><li><strong>Contexto <code>$this</code></strong> — Acceso al objeto de ejecución (<code>{{$this.firstName}}</code>, <code>{{$this.headers.Authorization}}</code>, <code>{{$this.methodName}}</code>, …) en formularios de entidad, Cliente HTTP, Ejecutor de métodos y Query Builder; resolución multipase entre campos hermanos.</li><li><strong>Variables dinámicas</strong> — Superficie Faker completa vía <code>{{$faker.module.method}}</code> (p. ej. <code>{{$faker.person.fullName}}</code>, <code>{{$faker.string.uuid}}</code>), más alias de reloj <code>{{$timestamp}}</code> / <code>{{$isoTimestamp}}</code>.</li><li><strong>Plantillas helper</strong> — <code>$pick</code> / <code>$sample</code> / <code>$unique</code> / <code>$repeat</code> / <code>$object</code> / <code>$vector</code> (y <code>$faker.helpers.*</code>) para listas, objetos JSON y arrays float tipo embedding; <code>count:n</code>, <code>count:min,max</code> o <code>count:&gt;=n</code> / <code>count:&lt;=n</code> para longitud dinámica; <code>$vector | dims:n</code> (opción <code>normalize</code>); la resolución profunda rehidrata hojas estructuradas exactas.</li><li><strong>Listas con nombre</strong> — Defina fuentes <code>$lists.nombre</code> fijas o respaldadas por dataclass en los ámbitos global, perfil o base; adminístrelas desde el conmutador <strong>Listas</strong> del pie y reutilícelas en plantillas <code>$pick</code>, <code>$sample</code> y <code>$unique</code>.</li><li><strong>Chips y autocompletado</strong> — Las variables conocidas se destacan como chips; sugerencias para claves de entorno, alias, helpers y rutas <code>$faker.*</code>; las claves sin resolver permanecen visibles como <code>{{…}}</code>.</li><li><strong>Exportar / Importar</strong> — Comparta entornos como JSON desde la barra del editor.</li><li><strong>API del terminal</strong> — Helpers <code>app.environment</code> y comandos <code>.env</code> / <code>.envs</code>.</li></ul><h4 id="carpetas-de-confianza" tabindex="-1">Carpetas de confianza <a class="header-anchor" href="#carpetas-de-confianza" aria-label="Permalink to &quot;Carpetas de confianza&quot;">​</a></h4><ul><li><strong>Lista de permitidos</strong> — En escritorio y móvil, añada carpetas locales (Home, Escritorio, Documentos o Descargas) con un alias. Los alias permanecen en este dispositivo y no forman parte de la exportación de perfil.</li><li><strong>Plantillas $files</strong> — <code>{{$files.photos}}</code> elige un archivo al azar, <code>{{$files.photos/cat.jpg}}</code> una ruta concreta, y <code>{{$files.photos/**/*.png}}</code> una coincidencia glob; opciones <code>| ext:</code> y <code>| recursive:false</code>.</li><li><strong>Gestor de archivos</strong> — Vista de lista o iconos, barra lateral y vista previa redimensionables, vista previa de imagen, y persistencia de la selección / carpetas expandidas.</li><li><strong>Copiar plantillas</strong> — Las acciones de vista previa copian los tokens <code>$files</code> con un tooltip de clic para copiar que pasa a Copiado.</li><li><strong>Confirmar al quitar</strong> — Quitar una carpeta de confianza pide confirmación; los archivos en disco no se eliminan.</li><li><strong>Navegación por teclado</strong> — Flechas, Inicio/Fin, Intro y Retroceso en el explorador; ↓ desde el filtro enfoca la lista.</li></ul><h4 id="terminal-orda" tabindex="-1">Terminal ORDA <a class="header-anchor" href="#terminal-orda" aria-label="Permalink to &quot;Terminal ORDA&quot;">​</a></h4><ul><li><strong>Dock inferior</strong> — Consola y Terminal comparten un panel redimensionable con pestañas; el estado abierto y la pestaña activa se guardan por perfil.</li><li><strong>REPL</strong> — Ejecute expresiones <code>ds.*</code> con resaltado Monaco, autocompletado del catálogo (también dentro de <code>query(&quot;…&quot;)</code>) e historial ↑/↓.</li><li><strong>Modo Código</strong> — Edite snippets <code>.js</code> con nombre; Enter = nueva línea, Mayús+Enter (o Ejecutar) lanza el código; <code>⌘/Ctrl+Enter</code> siempre ejecuta.</li><li><strong>Paquete de snippets</strong> — Exportar/importar gzip (<code>.orda-snippets.gz</code>); <code>.load</code> / <code>.run</code> / <code>.rm</code> con completado de nombres.</li><li><strong>Celdas de resultado</strong> — Entidades y selecciones se abren en pestañas; binarios/imágenes con los visores existentes; el tráfico REST aparece en Consola → Red.</li><li><strong>Comandos con punto</strong> — <code>.help</code>, <code>.exit</code>, etc.; ayuda en render compacto.</li></ul><h4 id="exportacion-rest" tabindex="-1">Exportación REST <a class="header-anchor" href="#exportacion-rest" aria-label="Permalink to &quot;Exportación REST&quot;">​</a></h4><ul><li><strong>Pestaña Exportación REST</strong> — Ábrala desde Herramientas o la paleta de comandos; un asistente en cuatro pasos (selección → categorías → variables → vista previa) genera una colección v2.1 o una spec OpenAPI 3.1 a partir del catálogo.</li><li><strong>Catálogo de peticiones</strong> — Auth, catalog, info, CRUD, entity sets, funciones dataclass / entity / entitySelection y singletons. Los métodos no expuestos y el login de directorio están desactivados por defecto.</li><li><strong>Vista previa</strong> — Expanda o contraiga carpetas (incluido expandir / contraer todo), active o no los emojis, Mayús+clic para aplicar o quitar un emoji por categoría, y opcionalmente adjunte la documentación oficial REST 4D a cada petición.</li><li><strong>Cliente HTTP y Ejecutor de métodos</strong> — Exporte también la petición actual o los favoritos como colección u OpenAPI.</li></ul><h4 id="movil" tabindex="-1">Móvil <a class="header-anchor" href="#movil" aria-label="Permalink to &quot;Móvil&quot;">​</a></h4><ul><li><strong>Apps iOS y Android</strong> — Shells nativos con perfiles de conexión, HTTP sin CORS y layouts safe-area.</li><li><strong>Dock táctil</strong> — Consola/Terminal como overlay con objetivos más grandes; hoja de compartir / Descargas para exportaciones.</li><li><strong>CI móvil</strong> — GitHub Actions construye y publica artefactos móviles (incluida la firma Android).</li></ul><h4 id="ejecutor-de-metodos" tabindex="-1">Ejecutor de métodos <a class="header-anchor" href="#ejecutor-de-metodos" aria-label="Permalink to &quot;Ejecutor de métodos&quot;">​</a></h4><ul><li><strong>Params y cabeceras Advanced</strong> — Params y Headers usan el mismo editor con pestañas subrayadas que el Cliente HTTP; el parámetro de consulta <code>$method=entityset</code> se rellena por defecto en nuevas ejecuciones (la UI es la fuente de verdad para <code>$method</code>).</li><li><strong>Errores en el panel de resultado</strong> — Errores de ejecución, red y cancelación aparecen en el panel de resultado (estado + cuerpo de error), como en el Cliente HTTP; los mensajes de validación permanecen bajo la configuración.</li><li><strong>Estados vacíos</strong> — Indicaciones claras de «seleccione un método» en los paneles de configuración y resultado hasta elegir un método; Ejecutar permanece deshabilitado (estilo outline) hasta entonces.</li><li><strong>Atajos mod-clic</strong> — <code>⌘/Ctrl+clic</code> abre una pestaña del Ejecutor de métodos en segundo plano; <code>⌘/Ctrl+Mayús+clic</code> abre la llamada en el Cliente HTTP (lista, favoritos, historial y selector de métodos).</li></ul><h4 id="consola-y-medios" tabindex="-1">Consola y medios <a class="header-anchor" href="#consola-y-medios" aria-label="Permalink to &quot;Consola y medios&quot;">​</a></h4><ul><li><strong>Vista previa de imagen de red</strong> — Vista previa en línea de respuestas de imagen en el registro de red.</li><li><strong>Peticiones en curso</strong> — El cuerpo de la petición se publica en cuanto arranca la llamada; <strong>Abrir en Cliente HTTP</strong> está disponible mientras la entrada sigue pending.</li><li><strong>Cancelar peticiones</strong> — Aborte llamadas de red en curso desde la consola cuando esté admitido.</li><li><strong>Compartir / guardar</strong> — Comparta o descargue objetos binarios e imágenes por rutas nativas (corrige fallos de descarga WKWebView en iOS).</li></ul><h4 id="favoritos-y-creacion" tabindex="-1">Favoritos y creación <a class="header-anchor" href="#favoritos-y-creacion" aria-label="Permalink to &quot;Favoritos y creación&quot;">​</a></h4><ul><li><strong>Favoritos del Cliente HTTP</strong> — Guarde, reabra y exporte favoritos (incluida la exportación collection / OpenAPI).</li><li><strong>Favoritos del Ejecutor de métodos</strong> — El mismo flujo de favoritos para llamadas a métodos.</li><li><strong>Creación de entidades por lotes</strong> — Cree varias entidades con campos con plantilla resueltos desde el mapa de entorno activo.</li></ul><h4 id="herramientas-de-seleccion" tabindex="-1">Herramientas de selección <a class="header-anchor" href="#herramientas-de-seleccion" aria-label="Permalink to &quot;Herramientas de selección&quot;">​</a></h4><ul><li><strong>Puntos de entrada</strong> — Menú de herramientas de selección en listas de dataclass, menús contextuales de pestañas, resultados de selección del Ejecutor, conjuntos relacionados, filas de Home y paleta de comandos.</li><li><strong>Analizar</strong> — Valores distintos (<code>$distinct</code>) y tarjetas de cálculo (<code>$compute=$all</code>) para un atributo del conjunto de entidades actual.</li><li><strong>Exportar / Importar</strong> — Formatos extensibles (JSON, JSON REST, JSONL, CSV, TSV, SQL, XML, YAML, Markdown, HTML); la importación crea o actualiza registros en la dataclass abierta.</li><li><strong>Anonimizar</strong> — Asignación de campos con plantillas Faker (filtros <code>|</code>), valores fijos, conservar o vaciar; quitar campos del plan para omitirlos de los payloads; semilla opcional; vista previa al estilo del Cliente HTTP con modo auto-detectado.</li><li><strong>Anonimización de imágenes</strong> — Los atributos Image editables aceptan plantillas de imagen Faker como <code>{{$faker.image.personPortrait | female}}</code>; los retratos generados se descargan, cargan mediante <code>$upload?$rawPict=true</code> y se sustituyen por IDs de carga 4D antes de exportar o escribir.</li><li><strong>Acciones de anonimización</strong> — Descargar datos anonimizados, importar como registros nuevos, o sobrescribir los campos asignados del conjunto actual (confirmación; <code>__KEY</code> / <code>__STAMP</code> más solo campos modificados); el progreso cubre recuperación, generación Faker, cargas de imágenes paralelas y finalización, con cancelación mientras el trabajo sigue pendiente.</li></ul><h4 id="ux" tabindex="-1">UX <a class="header-anchor" href="#ux" aria-label="Permalink to &quot;UX&quot;">​</a></h4><ul><li><strong>Acerca de</strong> — Diálogo de información desde el chrome móvil/escritorio.</li><li><strong>Alturas de paneles</strong> — La lista de entidades y paneles de petición recuerdan la altura; la altura de la consola se limita si el viewport es desconocido.</li><li><strong>Cliente HTTP (móvil)</strong> — Resumen de petición/respuesta adaptado a pantallas estrechas.</li><li><strong>Cargas binarias HTTP</strong> — Los selectores de cuerpo binario aceptan arrastrar y soltar en navegador y desktop, deducen el <code>Content-Type</code> del archivo seleccionado y sugieren endpoints <code>/rest/$upload?$rawPict=true</code> / <code>$binary=true</code>; los valores Content-Type completan tipos MIME comunes.</li><li><strong>Notificaciones del Cliente HTTP</strong> — Las respuestas que contienen <code>__WEBFORM.__NOTIFICATION</code> muestran la misma alerta tipada y el mismo sello de privilegio que los resultados del Ejecutor de métodos.</li><li><strong>Decodificación de URL en consola</strong> — Opción para decodificar URLs percent-encoded en el registro de red.</li><li><strong>Conmutador de entorno</strong> — Control del pie refinado para el perfil / base activos y el acceso a Gestionar.</li><li><strong>Editores de petición compartidos</strong> — El Cliente HTTP y el Ejecutor de métodos comparten el editor clave/valor Params/Headers para una edición Advanced coherente.</li><li><strong>Gesto conservar solo</strong> — Mayús+clic en una acción de papelera de asignaciones de campos, variables, listas con nombre, historial de peticiones, favoritos o filas clave/valor conserva ese elemento y elimina los demás tras confirmación.</li></ul><h3 id="documentacion-1" tabindex="-1">Documentación <a class="header-anchor" href="#documentacion-1" aria-label="Permalink to &quot;Documentación&quot;">​</a></h3><ul><li>Páginas de la guía <a href="https://midrissi.github.io/4d-dataexplorer/guide/console.html" target="_blank" rel="noreferrer">Consola</a>, <a href="https://midrissi.github.io/4d-dataexplorer/guide/terminal.html" target="_blank" rel="noreferrer">Terminal ORDA</a>, <a href="https://midrissi.github.io/4d-dataexplorer/guide/rest-export.html" target="_blank" rel="noreferrer">Exportación REST</a>, <a href="https://midrissi.github.io/4d-dataexplorer/guide/environments.html" target="_blank" rel="noreferrer">Variables de entorno</a>, <a href="https://midrissi.github.io/4d-dataexplorer/guide/trusted-folders.html" target="_blank" rel="noreferrer">Carpetas de confianza</a>, <a href="https://midrissi.github.io/4d-dataexplorer/guide/selection-tools.html" target="_blank" rel="noreferrer">Herramientas de selección</a> y <a href="https://midrissi.github.io/4d-dataexplorer/guide/mobile.html" target="_blank" rel="noreferrer">Apps móviles</a>.</li><li>La galería de inicio incluye el editor de entornos y capturas actualizadas (claro / oscuro).</li></ul><h3 id="correcciones-1" tabindex="-1">Correcciones <a class="header-anchor" href="#correcciones-1" aria-label="Permalink to &quot;Correcciones&quot;">​</a></h3><ul><li><strong>Descargas iOS</strong> — Las exportaciones de snippets y ajustes usan la ruta nativa en lugar de <code>&lt;a download&gt;</code> (NSURLError -3000).</li><li><strong>Restauración de pestaña</strong> — Recargar con el Terminal abierto ya no fuerza la Consola.</li><li><strong>Revelar entidad</strong> — Abrir una entidad desde el terminal usa la clave primaria en lugar de <code>$filter</code> sobre <code>__KEY</code>.</li><li><strong>Parámetros de consulta vacíos</strong> — La exportación de colección desactiva por defecto <code>$filter</code> / <code>$orderby</code> / <code>$attributes</code> vacíos para que no se envíen hasta rellenarlos.</li><li><strong>Respuestas OpenAPI</strong> — Las specs exportadas listan los estados REST 4D conocidos (200, 401, 402, 404, 500).</li><li><strong>Pestaña Docs de la colección</strong> — La documentación de cada petición incluye el markdown oficial de 4D REST, no solo un resumen.</li><li><strong>Filtros dinámicos</strong> — Género y rangos numéricos / de fecha en <code>$faker.*</code> se resuelven con opciones Faker.</li><li><strong>Alias Faker <code>userName</code></strong> — Las sugerencias y plantillas aceptan el nombre Faker v8 <code>internet.userName</code> como alias de <code>internet.username</code>.</li><li><strong>Plantillas en docs</strong> — La guía de entornos y la portada muestran ejemplos <code>{{…}}</code> sin romper el compilador Vue de VitePress.</li><li><strong>Resultados obsoletos del Ejecutor</strong> — Un fallo o cancelación ya no deja un éxito anterior bajo la configuración; los errores sustituyen la vista de resultado.</li><li><strong>Cuerpo de red en pending</strong> — Las entradas de consola ya no esperan a que termine la llamada para mostrar el cuerpo de petición saliente.</li></ul><h2 id="_1-3-x" tabindex="-1">1.3.x <a class="header-anchor" href="#_1-3-x" aria-label="Permalink to &quot;1.3.x&quot;">​</a></h2><h3 id="resumen-2" tabindex="-1">Resumen <a class="header-anchor" href="#resumen-2" aria-label="Permalink to &quot;Resumen&quot;">​</a></h3><p>La versión <code>1.3.x</code> introduce Data Explorer Desktop (Tauri + React) con perfiles de conexión persistentes, integración nativa de ventana y actualizaciones automáticas en la app; añade un Ejecutor de métodos para seleccionar y ejecutar métodos ORDA expuestos con argumentos tipados y vistas de resultado especializadas; añade un Cliente HTTP para componer y reenviar solicitudes REST; añade un panel Consola redimensionable que registra mensajes de la aplicación y cada solicitud HTTP; mejora el manejo de conexiones multiplataforma con soporte HTTP fetch; amplía el tratamiento de datos binarios con carga diferida de BLOB; optimiza el renderizado del grafo de estructura para esquemas grandes; y refina la retroalimentación del asistente y la accesibilidad en superficies clave de navegación.</p><h3 id="funcionalidades" tabindex="-1">Funcionalidades <a class="header-anchor" href="#funcionalidades" aria-label="Permalink to &quot;Funcionalidades&quot;">​</a></h3><h4 id="aplicacion-de-escritorio" tabindex="-1">Aplicación de escritorio <a class="header-anchor" href="#aplicacion-de-escritorio" aria-label="Permalink to &quot;Aplicación de escritorio&quot;">​</a></h4><ul><li><strong>Data Explorer Desktop</strong> - Nueva aplicación de escritorio construida con Tauri y React.</li><li><strong>Conexiones guardadas</strong> - Cree, edite y reutilice perfiles de conexión desde una pantalla de conexión dedicada en escritorio.</li><li><strong>Ventana y tema</strong> - Mejor comportamiento de inicio en escritorio con sincronización mejorada del estado de ventana y tema.</li><li><strong>Actualizador automático</strong> - Detección de actualizaciones y gestión del proceso en la app con notificaciones.</li><li><strong>Pipeline de lanzamiento macOS</strong> - El flujo de GitHub Actions ahora empaqueta y sube artefactos de escritorio para macOS.</li></ul><h4 id="ejecutor-de-metodos-1" tabindex="-1">Ejecutor de métodos <a class="header-anchor" href="#ejecutor-de-metodos-1" aria-label="Permalink to &quot;Ejecutor de métodos&quot;">​</a></h4><ul><li><strong>Pestaña Ejecutor de métodos</strong> - Configure y ejecute métodos 4D expuestos desde una pestaña dedicada; ábrala desde la paleta de comandos, las vistas de clase de datos y entidad, o el asistente.</li><li><strong>Llamadas según el alcance</strong> - Llame métodos de datastore, clase de datos, entidad y selección de entidades con expresiones al estilo ORDA (<code>ds.method</code>, <code>ds.Table.method</code>, <code>ds.Table.entity(key).method</code>, <code>ds.Table.sel(key).method</code>).</li><li><strong>Argumentos de ejecución</strong> - Construya argumentos posicionales como valores personalizados, referencias de entidad o selecciones de entidades; reordene, duplique y valide antes de ejecutar.</li><li><strong>Historial de ejecuciones</strong> - Vuelva a abrir ejecuciones correctas recientes; ⌘/Ctrl+clic en las claves del historial para abrir la entidad o selección relacionada.</li><li><strong>Vistas de resultado</strong> - Inspeccione resultados JSON, o abra automáticamente vistas previas especializadas de entidad y selección de entidades.</li></ul><h4 id="panel-consola" tabindex="-1">Panel Consola <a class="header-anchor" href="#panel-consola" aria-label="Permalink to &quot;Panel Consola&quot;">​</a></h4><ul><li><strong>Consola acoplada</strong> - Abra un panel inferior redimensionable desde la barra de estado o la paleta de comandos para inspeccionar registros mientras navega.</li><li><strong>Registro de red</strong> - Cada solicitud HTTP se registra con método, URL, estado, duración y tamaño de respuesta; expanda una entrada para inspeccionar cabeceras y cuerpos (secretos redactados).</li><li><strong>Abrir en el Cliente HTTP</strong> - Reproduzca una entrada de red capturada en el Cliente HTTP con método, URL, cabeceras y cuerpo saneados cuando estén disponibles.</li><li><strong>Filtros y controles</strong> - Filtre por nivel (todos, log, info, advertencia, error, red), contraiga todas las filas expandidas y limpie el búfer en memoria; los contadores de errores y advertencias aparecen en el botón Consola del pie de página.</li></ul><h4 id="cliente-http" tabindex="-1">Cliente HTTP <a class="header-anchor" href="#cliente-http" aria-label="Permalink to &quot;Cliente HTTP&quot;">​</a></h4><ul><li><strong>Pestaña Cliente HTTP</strong> - Compose y envíe solicitudes HTTP desde Herramientas o la paleta de comandos hacia el servidor actual o un origen personalizado.</li><li><strong>Editor de solicitud</strong> - Autocompletado de método, servidor y ruta; Params, Headers, Body (ninguno / formulario / urlencoded / raw / binario) y Settings.</li><li><strong>Inspector de respuesta</strong> - Estado, tiempo, tamaño, cabeceras, cookies y cuerpo tras Enviar (⌘/Ctrl+Enter).</li><li><strong>Opciones de escritorio</strong> - Control de cookies de sesión, timeouts, límites de redirección y omisión TLS opcional en builds de escritorio.</li></ul><h4 id="conectividad-y-carga-de-datos" tabindex="-1">Conectividad y carga de datos <a class="header-anchor" href="#conectividad-y-carga-de-datos" aria-label="Permalink to &quot;Conectividad y carga de datos&quot;">​</a></h4><ul><li><strong>Soporte HTTP fetch</strong> - Los flujos de conexión se actualizaron para admitir llamadas HTTP basadas en fetch en distintos entornos.</li><li><strong>Carga diferida de BLOB</strong> - Se mejora la carga de objetos binarios con recuperación de BLOB bajo demanda en el visor de entidades.</li></ul><h4 id="grafo-de-estructura-e-interfaz" tabindex="-1">Grafo de estructura e interfaz <a class="header-anchor" href="#grafo-de-estructura-e-interfaz" aria-label="Permalink to &quot;Grafo de estructura e interfaz&quot;">​</a></h4><ul><li><strong>Respuesta del grafo</strong> - El renderizado del grafo de clases de datos ahora usa estimación de dimensiones de tarjeta y comparaciones optimizadas de resaltado de nodos.</li><li><strong>Retroalimentación de actividad del asistente</strong> - El chatbot ahora muestra estados de carga más claros y un indicador animado de destellos.</li><li><strong>Mejoras de accesibilidad</strong> - Barra lateral, barra de pestañas, paleta de comandos y vistas relacionadas recibieron mejoras de accesibilidad y refinamiento semántico de clases.</li></ul><h3 id="correcciones-2" tabindex="-1">Correcciones <a class="header-anchor" href="#correcciones-2" aria-label="Permalink to &quot;Correcciones&quot;">​</a></h3><ul><li><strong>Renderizado de objetos binarios</strong> - Mejora de las rutas de manejo binario diferido en el visor de entidades.</li><li><strong>Estabilidad en edición de conexiones</strong> - Se estabilizaron los flujos de edición y actualización de conexiones en escritorio.</li><li><strong>Diseño HTML de cobertura</strong> - Se ajustó el padding en la salida HTML de cobertura generada para una visualización más limpia.</li></ul><h2 id="_1-2-x" tabindex="-1">1.2.x <a class="header-anchor" href="#_1-2-x" aria-label="Permalink to &quot;1.2.x&quot;">​</a></h2><h3 id="resumen-3" tabindex="-1">Resumen <a class="header-anchor" href="#resumen-3" aria-label="Permalink to &quot;Resumen&quot;">​</a></h3><p>La versión <code>1.2.x</code> añade un gestor visual de campos para los atributos mostrados (incluidas rutas de relación anidadas), la carga bajo demanda de entidades relacionadas, un panel de metadatos agrupado, un visor de objetos binarios, asistencia del lenguaje ORDA en el generador de consultas, un asistente IA con herramientas configurables, un constructor de esquema JSON, editores de código basados en Monaco, gestión de conjuntos de entidades en el generador de consultas, el editor de metadatos del asistente, mutaciones de entidades en lote, autenticación por clave de acceso, mejoras en el grafo de estructura incluido el ajuste a la vista, estados de carga y error del visor de entidades y mejoras de interfaz en el asistente y el generador de consultas.</p><h3 id="funcionalidades-1" tabindex="-1">Funcionalidades <a class="header-anchor" href="#funcionalidades-1" aria-label="Permalink to &quot;Funcionalidades&quot;">​</a></h3><h4 id="campos-mostrados" tabindex="-1">Campos mostrados <a class="header-anchor" href="#campos-mostrados" aria-label="Permalink to &quot;Campos mostrados&quot;">​</a></h4><ul><li><strong>Gestor de campos</strong> — Elija y reordene los atributos mostrados en columnas de tabla y tarjetas desde un único panel; la selección se conserva por pestaña.</li><li><strong>Atributos anidados</strong> — Profundice en las relaciones para seleccionar atributos anidados (p. ej. <code>company.name</code>, y más profundo) tanto para la vista de tabla como de tarjetas.</li><li><strong>Selección por vista</strong> — Mantenga listas de atributos independientes para la vista de tabla y de tarjetas; arrastre para reordenar.</li><li><strong>Guardar como predeterminado</strong> — Guarde la selección actual como predeterminada para una clase de datos, o restablezca los valores predeterminados.</li></ul><h4 id="visor-de-entidades" tabindex="-1">Visor de entidades <a class="header-anchor" href="#visor-de-entidades" aria-label="Permalink to &quot;Visor de entidades&quot;">​</a></h4><ul><li><strong>Relaciones diferidas</strong> — Cargue entidades y conjuntos de entidades relacionados bajo demanda, en línea en las vistas de formulario y árbol.</li><li><strong>Tabla compartida para relaciones</strong> — Los conjuntos de entidades relacionados se muestran en la misma cuadrícula de datos que la vista de tabla.</li><li><strong>Panel de metadatos</strong> — Los atributos de sistema de 4D (<code>__KEY</code>, <code>__STAMP</code>, <code>__TIMESTAMP</code>, …) se agrupan en un panel de metadatos plegable.</li><li><strong>Todos los atributos en el detalle</strong> — La vista de detalle siempre muestra todos los atributos, incluso cuando el gestor de campos limita las columnas o campos en la lista.</li><li><strong>Campos de tarjeta expandibles</strong> — Las tarjetas muestran una vista previa de los primeros campos con un botón Mostrar más / Mostrar menos.</li><li><strong>Visor de objetos binarios</strong> — Previsualice objetos binarios privados de 4D (blobs e imágenes) directamente en el formulario y el visor de entidades.</li><li><strong>Indicadores de carga</strong> — Los datos de entidad muestran un estado de carga durante la obtención, incluidas las entidades y conjuntos de entidades relacionados.</li><li><strong>Recuperación ante errores</strong> — Cuando las entidades no se pueden cargar, un panel integrado permite reintentar, restablecer la consulta o cerrar la pestaña.</li><li><strong>Imágenes diferidas</strong> — Los atributos de imagen se cargan bajo demanda en las celdas de la tabla y el visor de entidades.</li><li><strong>Tooltips de celda</strong> — Pase el cursor sobre celdas truncadas de la tabla para ver el valor completo.</li><li><strong>Ordenación de columnas</strong> — Ordene las tablas de entidades por columna, incluidas las tablas de entidades relacionadas.</li></ul><h4 id="editor-de-metadatos-del-asistente" tabindex="-1">Editor de metadatos del asistente <a class="header-anchor" href="#editor-de-metadatos-del-asistente" aria-label="Permalink to &quot;Editor de metadatos del asistente&quot;">​</a></h4><ul><li><strong>Pestaña Editor de metadatos</strong> — Documente clases de datos, atributos, métodos, singletons y métodos de catálogo para el asistente IA; abrir desde Herramientas, la paleta de comandos o la barra del asistente.</li><li><strong>Generación de descripciones con IA</strong> — Genere descripciones por campo o en lote para todas las entradas faltantes; generación opcional de esquema JSON para parámetros de método.</li><li><strong>Indicadores de descripciones faltantes</strong> — Resalte elementos sin documentación; filtre la barra lateral para mostrar solo entradas faltantes.</li><li><strong>Editor JSON</strong> — Edite el objeto de metadatos completo directamente; exporte el esquema como archivo JSON.</li></ul><h4 id="asistente-ia" tabindex="-1">Asistente IA <a class="header-anchor" href="#asistente-ia" aria-label="Permalink to &quot;Asistente IA&quot;">​</a></h4><ul><li><strong>Panel del asistente</strong> — Panel de chat IA con herramientas para consultar datos, navegar entre pestañas, ejecutar comandos y controlar la interfaz.</li><li><strong>Herramientas configurables</strong> — Active o desactive espacios de nombres e herramientas individuales del asistente en Ajustes.</li><li><strong>Modo pantalla completa</strong> — Expanda el panel del asistente a pantalla completa; pulse Escape para salir.</li><li><strong>Copiar traza</strong> — Copie la traza de actividad del asistente al portapapeles desde el panel de actividad.</li><li><strong>Diagramas Mermaid</strong> — Renderizado y manejo de errores mejorados para gráficos Mermaid en las respuestas del asistente.</li></ul><h4 id="operaciones-de-datos" tabindex="-1">Operaciones de datos <a class="header-anchor" href="#operaciones-de-datos" aria-label="Permalink to &quot;Operaciones de datos&quot;">​</a></h4><ul><li><strong>Creación/actualización de entidades en lote</strong> — Cree o actualice varias entidades en una llamada mediante la API y las herramientas datastore del asistente.</li></ul><h4 id="constructor-de-esquema-json" tabindex="-1">Constructor de esquema JSON <a class="header-anchor" href="#constructor-de-esquema-json" aria-label="Permalink to &quot;Constructor de esquema JSON&quot;">​</a></h4><ul><li><strong>Pestaña Constructor de esquema</strong> — Editor visual para construir esquemas JSON; abrir desde el menú Herramientas en el pie.</li><li><strong>Editor de objetos</strong> — Expandir o contraer objetos anidados y configurar atributos del esquema.</li></ul><h4 id="editor-de-codigo" tabindex="-1">Editor de código <a class="header-anchor" href="#editor-de-codigo" aria-label="Permalink to &quot;Editor de código&quot;">​</a></h4><ul><li><strong>Editor Monaco</strong> — Editores de código y JSON con autocompletado de esquema en toda la aplicación.</li><li><strong>Preferencias del editor</strong> — Configure tamaño de fuente, ajuste de línea y barra de herramientas en Ajustes; se aplica a formularios de entidades, el constructor de esquema y otros editores.</li></ul><h4 id="consultas-y-conjuntos-de-entidades" tabindex="-1">Consultas y conjuntos de entidades <a class="header-anchor" href="#consultas-y-conjuntos-de-entidades" aria-label="Permalink to &quot;Consultas y conjuntos de entidades&quot;">​</a></h4><ul><li><strong>Asistencia del lenguaje ORDA</strong> — Autocompletado, información al pasar el cursor y ayuda de firmas para expresiones de consulta ORDA, con resolución de tipos basada en el catálogo.</li><li><strong>Operaciones con conjuntos de entidades</strong> — Combine conjuntos de entidades (<code>AND</code> / <code>OR</code> / <code>EXCEPT</code> / <code>INTERSECT</code>) y libere conjuntos de entidades mediante la API y las herramientas del asistente.</li><li><strong>Vinculación de conjuntos</strong> — Vincule pestañas de clases de datos a ID de conjuntos de entidades del servidor existentes; cargue, copie y edite ID en el generador de consultas.</li><li><strong>Caché de conjuntos</strong> — Los conjuntos de entidades del servidor se almacenan en caché y se liberan al cerrar pestañas.</li><li><strong>Parámetros de filtro</strong> — Defina parámetros de filtro tipados para expresiones de filtro parametrizadas en el generador de consultas.</li></ul><h4 id="perfiles-y-apariencia" tabindex="-1">Perfiles y apariencia <a class="header-anchor" href="#perfiles-y-apariencia" aria-label="Permalink to &quot;Perfiles y apariencia&quot;">​</a></h4><ul><li><strong>Cambio rápido de perfil</strong> — Cambie de perfil desde el pie sin abrir Ajustes; el icono y color del perfil se muestran en la barra de estado.</li><li><strong>Apariencia por perfil</strong> — Personalice cada perfil con un icono y un color.</li><li><strong>Tema Qodly</strong> — Nuevo tema Qodly en modos claro y oscuro (tipografía Roboto, acento violeta).</li></ul><h4 id="grafo-de-estructura" tabindex="-1">Grafo de estructura <a class="header-anchor" href="#grafo-de-estructura" aria-label="Permalink to &quot;Grafo de estructura&quot;">​</a></h4><ul><li><strong>Firmas de métodos</strong> — Firmas de métodos resaltadas en el grafo de estructura.</li><li><strong>Indicadores de atributos</strong> — Atributos expuestos y conexiones de relación resaltados visualmente en los nodos de clases de datos.</li><li><strong>Navegación estable</strong> — Los clics repetidos en una clase de datos ya no vacían el grafo; la ventana gráfica se valida y la selección de nodos se conserva.</li><li><strong>Ajustar a la vista</strong> — Recentre y haga zoom en el grafo de estructura para mostrar todos los nodos visibles.</li></ul><h4 id="autenticacion-e-internacionalizacion" tabindex="-1">Autenticación e internacionalización <a class="header-anchor" href="#autenticacion-e-internacionalizacion" aria-label="Permalink to &quot;Autenticación e internacionalización&quot;">​</a></h4><ul><li><strong>Inicio de sesión con clave de acceso</strong> — Inicie sesión con una clave de acceso REST cuando el servidor requiera autenticación.</li><li><strong>Internacionalización</strong> — Traducciones ampliadas en la interfaz del asistente, el generador de consultas y otros componentes.</li></ul><h3 id="correcciones-3" tabindex="-1">Correcciones <a class="header-anchor" href="#correcciones-3" aria-label="Permalink to &quot;Correcciones&quot;">​</a></h3><ul><li><strong>Estado de pestañas</strong> — El estado por pestaña se mantiene coherente al cambiar de pestaña (sincronización de la pestaña activa); el ID de la pestaña activa se valida antes de cerrar pestañas o establecer ID de conjuntos de entidades.</li><li><strong>Atajos de perfil</strong> — Los atajos se fusionan con los valores predeterminados al cargar perfiles, evitando que una lista vacía borre los atajos configurados.</li><li><strong>Ventana del grafo de estructura</strong> — El desplazamiento/zoom programático ya no corrompe el estado guardado de la ventana.</li><li><strong>Edición en vista de lista</strong> — Edición en tabla desactivada en vista de lista para evitar cambios accidentales.</li><li><strong>Orden de activación de pestañas</strong> — Cerrar una pestaña ahora activa la pestaña usada más recientemente en lugar de la adyacente.</li></ul><hr><h2 id="_1-1-x" tabindex="-1">1.1.x <a class="header-anchor" href="#_1-1-x" aria-label="Permalink to &quot;1.1.x&quot;">​</a></h2><h3 id="resumen-4" tabindex="-1">Resumen <a class="header-anchor" href="#resumen-4" aria-label="Permalink to &quot;Resumen&quot;">​</a></h3><p>La versión <code>1.1.x</code> ofrece un 4D REST Explorer refinado para explorar clases de datos y entidades, con gestión de perfiles, barra de búsqueda global, modos rápidos de la paleta de comandos, mejoras en atajos de teclado, selección de idioma y un conjunto de capacidades centradas en la visualización y edición de datos.</p><h3 id="funcionalidades-2" tabindex="-1">Funcionalidades <a class="header-anchor" href="#funcionalidades-2" aria-label="Permalink to &quot;Funcionalidades&quot;">​</a></h3><h4 id="inicio-y-navegacion" tabindex="-1">Inicio y navegación <a class="header-anchor" href="#inicio-y-navegacion" aria-label="Permalink to &quot;Inicio y navegación&quot;">​</a></h4><ul><li><strong>Pantalla de bienvenida</strong> — Resumen de tu base de datos: estadísticas, número de entidades y gráficos (<code>bar</code> y <code>pie</code>)</li><li><strong>Barra de búsqueda global</strong> — Barra de búsqueda en la cabecera; haz clic o enfoca para abrir la paleta de comandos.</li><li><strong>Paleta de comandos</strong> — Abrir entidades por ID, abrir una clase de datos o buscar clases desde un solo lugar</li><li><strong>Comandos recientes</strong> — Los comandos usados recientemente aparecen arriba en la paleta con un icono de reloj; el historial se guarda por perfil.</li><li><strong>Modos rápidos</strong> — Desde la búsqueda de la paleta, escribe <code>:</code> para ir a una entidad por índice, <code>&gt;</code> para elegir una clase (vista estructura), <code>/</code> para abrir los datos de una clase, o <code>@</code> para cambiar de pestaña.</li><li><strong>Atajos de teclado</strong> — Atajos personalizados para acciones habituales (<code>paleta de comandos</code>, <code>ajustes</code>, <code>tema</code>, <code>estructura</code>, etc.)</li><li><strong>Interfaz con pestañas</strong> — Fijar pestañas, cerrar otras o reordenar arrastrando</li><li><strong>Pestaña Notas de versión</strong> — Abrir las notas de versión desde la barra de estado (pie); el contenido se muestra en una pestaña dedicada</li><li><strong>Idioma</strong> — Elegir el idioma de la app (inglés, francés, español) desde la barra de estado (pie); las notas de versión y la interfaz siguen el idioma seleccionado.</li></ul><h4 id="clase-de-datos-y-entidades" tabindex="-1">Clase de datos y entidades <a class="header-anchor" href="#clase-de-datos-y-entidades" aria-label="Permalink to &quot;Clase de datos y entidades&quot;">​</a></h4><ul><li><strong>Navegador de clases</strong> — Trabajar con varias clases de datos en pestañas y cambiar entre disposición en tarjetas y tabla</li><li><strong>Constructor de consultas</strong> — Filtro, ordenación, selección de campos y límite; panel de consulta colapsable</li><li><strong>Lista de entidades</strong> — Lista paginada en un panel redimensionable con badges del número de entidades</li><li><strong>Visor de entidad</strong> — Inspeccionar el <code>JSON</code> de la entidad y crear, editar o eliminar entidades (salvo si el modo solo lectura está activado)</li><li><strong>Ir a entidad</strong> — Abrir una entidad por ID desde la paleta de comandos</li></ul><h4 id="estructura-y-visualizacion" tabindex="-1">Estructura y visualización <a class="header-anchor" href="#estructura-y-visualizacion" aria-label="Permalink to &quot;Estructura y visualización&quot;">​</a></h4><ul><li><strong>Grafo de estructura</strong> — Diagrama de clases de datos y sus enlaces; resaltar una clase desde el menú contextual de la pestaña</li><li><strong>Aspecto de clases</strong> — Colores e iconos por clase en Ajustes</li></ul><h4 id="perfiles-y-ajustes" tabindex="-1">Perfiles y ajustes <a class="header-anchor" href="#perfiles-y-ajustes" aria-label="Permalink to &quot;Perfiles y ajustes&quot;">​</a></h4><ul><li><strong>Gestión de perfiles</strong> — Crear, renombrar, duplicar y eliminar perfiles en Ajustes. Cada perfil tiene su propio tema, atajos, ancho de la barra lateral y otras preferencias.</li><li><strong>Importar / exportar</strong> — Exportar todos los ajustes o perfiles seleccionados a un archivo JSON, e importar ajustes o perfiles desde un archivo (con la opción de elegir qué perfiles importar).</li></ul><h4 id="ajustes-y-apariencia" tabindex="-1">Ajustes y apariencia <a class="header-anchor" href="#ajustes-y-apariencia" aria-label="Permalink to &quot;Ajustes y apariencia&quot;">​</a></h4><ul><li><strong>Apariencia</strong> — Varios temas de color (<code>Slate</code>, <code>Tangerine</code>, <code>Violet Bloom</code>, <code>Graphite</code>, <code>Aurora</code>, etc.)</li><li><strong>Modo claro / oscuro</strong> — Seguir el sistema o cambiar manualmente</li><li><strong>Vistas por defecto</strong> — Elegir disposición por defecto (<code>tarjetas</code> o <code>tabla</code>) y tamaño de página para nuevas pestañas de clase</li><li><strong>Atajos de teclado</strong> — Activar o desactivar atajos y ver la lista completa en Ajustes</li><li><strong>Aspecto de clases</strong> — Definir colores e iconos para cada clase en la barra lateral y las pestañas</li></ul><h4 id="atajos-de-teclado" tabindex="-1">Atajos de teclado <a class="header-anchor" href="#atajos-de-teclado" aria-label="Permalink to &quot;Atajos de teclado&quot;">​</a></h4><ul><li><strong>Modal de atajos</strong> — La sección «Vista» se muestra ahora en dos columnas para un diseño más compacto.</li><li><strong>Grabar como acorde</strong> — La opción «Grabar como acorde (secuencia de dos teclas)» está ahora en el modal de grabación de atajo, para poder elegir el modo acorde al grabar un atajo.</li><li><strong>Visualización de atajos</strong> — Los botones de atajo en Ajustes usan un estilo más ligero, solo con borde (sin fondo) para las teclas.</li></ul><h4 id="seguridad-y-modos" tabindex="-1">Seguridad y modos <a class="header-anchor" href="#seguridad-y-modos" aria-label="Permalink to &quot;Seguridad y modos&quot;">​</a></h4><ul><li><strong>Modo solo lectura</strong> — Interruptor en la cabecera para desactivar crear/editar/eliminar y navegar con seguridad</li><li><strong>Modo edición</strong> — Crear, actualizar y eliminar entidades cuando está activado</li></ul><h3 id="tecnico" tabindex="-1">Técnico <a class="header-anchor" href="#tecnico" aria-label="Permalink to &quot;Técnico&quot;">​</a></h3><ul><li><strong>API REST 4D</strong> — Comunicación con tu servidor 4D por REST y soporte de parámetros de consulta estándar</li><li><strong>Estado persistente</strong> — Pestañas, ancho de la barra lateral y ajustes almacenados por base (<code>BASEID</code>)</li></ul>',123)])])}const m=a(n,[["render",i]]);export{g as __pageData,m as default};
